export default function ({ events, previous }) {
  let i = previous?.index ?? 0;
  while (i < events.length && events[i].mimeType !== "application/pdf") i++;
  return {
    more: i < events.length,
    state: { index: i + 1 },
    file: i < events.length ? events[i] : { fileId: "none", name: "", mimeType: "" },
  };
}

