export default async function ({ file }, ctx) {
  if (!file?.fileId) throw Error("Missing Drive file ID");
  let key = "invoice201:" + file.fileId,
    s = await ctx.state.get(key);
  if (s?.phase?.endsWith("-pending"))
    throw Error("Inspect external service before retrying pending invoice");
  if (s?.phase === "done") return { key, mode: "done" };
  if (s?.parentId && s.items) return { key, mode: "lines" };
  if (s?.items) return { key, mode: "parent" };
  if (s?.jobId) return { key, mode: "poll" };
  if (s?.fileId) return { key, mode: "job" };
  await ctx.state.set(key, { phase: "upload-pending", name: file.name });
  return { key, mode: "upload" };
}

