export default function ({ body }) {
  const status = body?.job?.status;
  if (["PENDING", "RUNNING"].includes(status)) return { ready: false, markdown: "" };
  if (
    status !== "COMPLETED" ||
    !Array.isArray(body.markdown?.pages) ||
    !body.markdown.pages.length ||
    body.markdown.pages.some((p) => p.success !== true || typeof p.markdown !== "string")
  )
    throw Error("Parse failed or incomplete");
  return { ready: true, markdown: body.markdown.pages.map((p) => p.markdown).join("\n\n") };
}

