export default async function ({ key, result }, ctx) {
  const items = result?.items;
  if (!Array.isArray(items) || !items.length) throw Error("Invoice contains no extracted items");
  let s = await ctx.state.get(key);
  if (!s.items) await ctx.state.set(key, { ...s, phase: "parsed", items });
  return { ok: true };
}

