export default async function ({ key }, ctx) {
  let s = await ctx.state.get(key);
  if (s?.phase === "parent-pending") throw Error("Inspect invoice table before retry");
  if (s?.parentId) return { skip: true, records: [{ fields: {} }] };
  await ctx.state.set(key, { ...s, phase: "parent-pending" });
  return { skip: false, records: [{ fields: { Name: s.name || "Invoice" } }] };
}

