export default async function ({ key }, ctx) {
  let s = await ctx.state.get(key),
    i = s?.index ?? 0;
  if (!s?.parentId || !Array.isArray(s.items)) throw Error("Missing invoice or items");
  if (s.phase === "line-pending") throw Error("Inspect line item table before retry");
  if (i >= s.items.length) {
    await ctx.state.set(key, { ...s, phase: "done" });
    return { more: false, records: [{ fields: {} }] };
  }
  const num = (x) => {
      const n = Number(String(x).replace(/[$,\s]/g, ""));
      if (!Number.isFinite(n)) throw Error("Invalid invoice amount");
      return n;
    },
    batch = s.items.slice(i, i + 10).map((item) => ({
      fields: {
        Description: item.description,
        Qty: num(item.qty),
        "Unit price": num(item.unit_price),
        Amount: num(item.amount),
        Invoices: [s.parentId],
      },
    }));
  await ctx.state.set(key, { ...s, phase: "line-pending", batchSize: batch.length });
  return { more: true, records: batch };
}

