export default async function ({ key, response }, ctx) {
  let s = await ctx.state.get(key);
  if (!Array.isArray(response) || response.length !== s?.batchSize || response.some((x) => !x.id))
    throw Error("Unknown line creation");
  await ctx.state.set(key, { ...s, phase: "lines", index: s.index + s.batchSize });
  return { ok: true };
}
